248→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
249→              currentTextRef.current = '';
250→            }
251→            segmentsRef.current.push({ type: 'error', errorMessage: error });
252→            setMessages((prev) =>
253→              prev.map((m) =>
254→                m.id === assistantId
255→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
256→                  : m
257→              )
258→            );
259→            setIsStreaming(false);
260→            abortRef.current = null;
261→          },
262→          onUserQuestion: (data) => {
263→            if (flushTimerRef.current) {
