266→            }
267→            flushText();
268→            if (currentTextRef.current.trim()) {
269→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
270→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
271→              currentTextRef.current = '';
272→            }
273→            segmentsRef.current.push({
274→              type: 'user_question',
275→              questionData: data,
276→            });
277→            setMessages((prev) =>
278→              prev.map((m) =>
279→                m.id === assistantId
280→                  ? { ...m, segments: [...segmentsRef.current] }
281→                  : m
282→              )
283→            );
284→          },
285→        },
286→        controller.signal,
287→        userSessionId,
288→      );
289→    },
290→    [isStreaming, flushText, refreshTables, userSessionId]
291→  );
