// Common SDK options (without resume/prompt — those vary on retry)
const baseOptions = {
  model: modelName,
  systemPrompt: body.system_prompt,
  allowedTools: ["Task", "mcp__duckdb-data-agent__execute_sql", "mcp__duckdb-data-agent__ask_user_question", "mcp__duckdb-data-agent__render_chart"] as string[],
  permissionMode: "bypassPermissions" as const,
  allowDangerouslySkipPermissions: true,
  maxTurns: 20,
  includePartialMessages: true,
  abortController,
  env: sdkEnv,
  stderr: (line: string) => {
    stderrLines.push(line);
    console.error(`[sidecar:cli] ${line}`);
  },
  ...(sdkAgents ? { agents: sdkAgents } : {}),
  ...(body.mcp_server_url
    ? {
        mcpServers: {
          "duckdb-data-agent": {
            type: "sse" as const,
            url: body.mcp_server_url,
          },
        },
      }
    : {}),
};

// Try with resume first; if the session is gone (container was recreated),
// retry without resume and prepend conversation history into the prompt.
let sdkQuery: ReturnType<typeof query>;
try {
  sdkQuery = query({
    prompt: body.message,
    options: {
      ...baseOptions,
      ...(body.session_id ? { resume: body.session_id } : {}),
    },
  });
  // Eagerly pull the first message to surface resume errors early
  const firstResult = await sdkQuery[Symbol.asyncIterator]().next();
  // Re-wrap into an async generator that yields the first result then the rest
  const firstMessage = firstResult.done ? null : firstResult.value;
  const originalIter = sdkQuery;
  sdkQuery = (async function* () {
    if (firstMessage) yield firstMessage;
    yield* originalIter;
  })() as ReturnType<typeof query>;
} catch (resumeErr: unknown) {
  const errStr = resumeErr instanceof Error ? resumeErr.message : String(resumeErr);
  if (errStr.includes("No conversation found") && body.conversation_history && body.conversation_history.length > 0) {
    console.log(`[sidecar] Resume failed ("No conversation found"), retrying with history prepended reqId=${requestId}`);
    // Build message with history prepended — mirrors backend _build_message_with_history
    let messageWithHistory = "Previous conversation (for context):\n";
    for (const entry of body.conversation_history) {
      const role = (entry.role || "user").charAt(0).toUpperCase() + (entry.role || "user").slice(1);
      messageWithHistory += `\n${role}: ${entry.content}\n`;
    }
    messageWithHistory += `\n---\n\nMy new message:\n${body.message}`;

    stderrLines.length = 0; // clear stderr from failed attempt
    sdkQuery = query({
      prompt: messageWithHistory,
      options: baseOptions,
    });
  } else {
    throw resumeErr;
  }
}

console.log(
  `[sidecar] SDK query started model=${modelName} reqId=${requestId}`
);

